from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict_with_key


class QosflowDisp(EgateCommandBase):
    """
    Parser for qosrule_disp command output.
    """

    # class naming convention for future extensions:
    # x = @classmethod contructor name
    # __created_with__ = x
    # parse_x  --> parsing method name
    # output_x --> pyparsing parser name

    def __init__(self, **params):
        """

        :param params:
        """
        super(QosflowDisp, self).__init__()
        self.command = 'qosflow_disp'
        self.params = params
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def _build_command(self):
        """
        Build qosflow_disp command.

        :return: None
        """
        for param, value in list(self.params.items()):
            self.to_execute += ' {}={}'.format(param, value)

    @classmethod
    def without_id_by_qosflow(cls):
        """

        :return:
        """
        self = cls()
        self.__created_with__ = 'without_id_by_qosflow'
        self.executed_phrase = r'.*?Configured Qos Flows.*?EGATE>'
        return self

    @classmethod
    def without_id_by_fiveqi(cls):
        """

        :return:
        """
        self = cls()
        self.__created_with__ = 'without_id_by_fiveqi'
        self.executed_phrase = r'.*?Configured Qos Flows.*?EGATE>'
        return self

    @classmethod
    def with_id(cls, qosrule_id):
        """

        :param enb_id:
        :return:
        """
        self = cls(id=qosrule_id)
        self.__created_with__ = 'with_id'
        self.executed_phrase = r'.*?QoS Flow\-\d+.*?EGATE>'
        return self

    def execute_and_parse(self, egate_id=0):
        """

        :return:
        """
        status, output = self.execute(egate_id=egate_id, command=self.to_execute)
        if status:
            fun = getattr(self, 'parse_%s' % str(self.__created_with__))
            parsed_output = fun(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output

    def parse_without_id_by_qosflow(self, cmd_input):
        """

        :param cmd_input:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_input)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Id', list_of_output_parsed_lines=output)

    def parse_without_id_by_fiveqi(self, cmd_input):
        """

        :param cmd_input:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_input)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='FiveQI', list_of_output_parsed_lines=output)

    def parse_with_id(self, cmd_input):
        """

        :param cmd_input:
        :return:
        """
        cmd_parser = EgateDispCommandsOutputParser(cmd_input)
        output = cmd_parser.get_list_of_output_parsed_lines()
        return create_dict_with_key(key='Parameter', list_of_output_parsed_lines=output)
